CustomFunction.Calculation:
// Iterates over a ¶-delimited list of HAVING condition tokens.
// Same structure as QueryParseWheresIter but calls QueryParseHavingCondition.
// condList: output of QueryParseSplitBooleans with Char(28) replaced by ¶.
// condCount: ValueCount of condList. index: 1-based.
Let
(
[
_raw = GetValue ( condList ; index ) ;
_isOr  = Left ( _raw ; 4 ) = " OR " ;
_isAnd = Left ( _raw ; 5 ) = " AND " ;
_boolean = If ( _isOr ; "or" ; "and" ) ;
_condition = Trim ( Case (
	_isAnd ; Middle ( _raw ; 6 ; Length ( _raw ) ) ;
	_isOr  ; Middle ( _raw ; 5 ; Length ( _raw ) ) ;
	_raw
	) ) ;
_q1 = QueryParseHavingCondition ( query ; _condition ; _boolean ) ;
_rest = If ( index < condCount ;
	QueryParseHavingsIter ( _q1 ; condList ; condCount ; index + 1 ) ;
	_q1
	)
] ;
_rest
)
